def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            comps.append((color, cells))

    # Find a substantial L-shaped component, which indicates the color to copy.
    choices = []
    for color, cells in comps:
        for r, c in cells:
            row = [x for y, x in cells if y == r]
            col = [y for y, x in cells if x == c]
            if len(row) >= 3 and len(col) >= 3:
                # Require the component to actually have arms at this corner.
                horiz = 1 if max(row) > c else -1
                vert = 1 if max(col) > r else -1
                if min(row) < c < max(row):
                    horiz = 1 if max(row)-c > c-min(row) else -1
                if min(col) < r < max(col):
                    vert = 1 if max(col)-r > r-min(col) else -1
                choices.append((len(cells), color, cells, (r, c), horiz, vert))
    if not choices:
        return [row[:] for row in grid]

    _, donor, bar, (cr, cc), horiz, vert = max(choices)
    # The vertical arm's far endpoint guides selection; look across the
    # horizontal arm, choosing the nearest separate object on that side.
    vertical_rows = [r for r, c in bar if c == cc]
    end_r = min(vertical_rows) if vert < 0 else max(vertical_rows)
    best = None
    for color, cells in comps:
        if color == donor:
            continue
        eligible = [(r, c) for r, c in cells if (c - cc) * horiz < 0]
        if not eligible:
            continue
        dist = min(abs(r - end_r) + abs(c - cc) for r, c in eligible)
        if best is None or dist < best[0]:
            best = (dist, cells)

    out = [row[:] for row in grid]
    if best:
        for r, c in best[1]:
            out[r][c] = donor
    return out
